# Demonstrating Fixtures 🔄

Let's see how `setUp` and `tearDown` interact with multiple tests.

<!-- FULL_CODE_START
import unittest

class BankAccount:
    def __init__(self, balance=0):
        self.balance = balance

class TestBankAccount(unittest.TestCase):
    def setUp(self):
        print("\n[setUp] Creating a fresh bank account...")
        self.account = BankAccount(100)

    def tearDown(self):
        print("[tearDown] Destroying the bank account...\n")
        self.account = None

    def test_deposit(self):
        print("Running test_deposit...")
        self.account.balance += 50
        self.assertEqual(self.account.balance, 150)

    def test_withdraw(self):
        print("Running test_withdraw...")
        self.account.balance -= 20
        self.assertEqual(self.account.balance, 80)

if __name__ == '__main__':
    unittest.main(verbosity=2, exit=False)
FULL_CODE_END -->

Notice the order of print statements: `setUp` -> `test_1` -> `tearDown` -> `setUp` -> `test_2` -> `tearDown`.

# Putting it all together 🧩

Let's write a comprehensive test case for a simple `ShoppingCart` class.

<!-- FULL_CODE_START
import unittest

class ShoppingCart:
    def __init__(self):
        self.items = {}

    def add_item(self, item, price):
        if price < 0:
            raise ValueError("Price cannot be negative")
        self.items[item] = price

    def total(self):
        return sum(self.items.values())

class TestShoppingCart(unittest.TestCase):
    def setUp(self):
        self.cart = ShoppingCart()

    def test_add_item(self):
        self.cart.add_item("Apple", 1.00)
        self.assertIn("Apple", self.cart.items)
        self.assertEqual(self.cart.items["Apple"], 1.00)

    def test_total(self):
        self.cart.add_item("Apple", 1.00)
        self.cart.add_item("Banana", 2.50)
        self.assertEqual(self.cart.total(), 3.50)

    def test_negative_price_raises_error(self):
        with self.assertRaisesRegex(ValueError, "cannot be negative"):
            self.cart.add_item("Debt", -50.00)

if __name__ == '__main__':
    unittest.main(verbosity=2, exit=False)
FULL_CODE_END -->
